// Monthly revenue report on the event store
// build {{sim.sessionId}}
export function monthlyRevenue(events: { type: string; amount: number }[]): number {
  return events.filter((e) => e.type === 'invoice.paid').reduce((sum, e) => sum + e.amount, 0);
}

// Churn report on the event store
// build {{sim.sessionId}}
export const churnReport = (ended: number, active: number) => (active ? ended / active : 0);

// Cohort report on the event store
// build {{sim.sessionId}}
export const cohortOf = (signupMonth: string) => signupMonth.slice(0, 7);
